import {applyGraphics} from './graphics.js?v=4.6.1';
import {normalizeSettings} from './settings.js?v=4.6.1';
import {Game} from './game.js?v=4.6.1';
import {CHAPTERS,PAGES,TILE} from './data.js?v=4.6.1';
import {MEMORY_IDS,SCENES} from './story.js?v=4.6.1';
const $=s=>document.querySelector(s);
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;let settings=normalizeSettings({},reducedMotion);
try{settings=normalizeSettings(JSON.parse(localStorage.getItem('resident-espey-settings')),reducedMotion);}catch{}
let game,current='',returnMenu='';
const controls=[['Move','W A S D'],['Look / fire','Mouse / Click'],['Aim','Right click'],['Interact','E'],['Reload','R'],['Switch weapon','1 / 2 / 3 or wheel'],['Knife','F'],['Dodge','Space'],['Sprint','Shift'],['Crouch','Ctrl / C'],['Quick turn','X'],['Flashlight','G'],['First aid','Q'],['Map','M'],['Notebook','J'],['Pause','Esc / P'],['Keyboard look','Arrows']];
const ui={
 isOpen(){return !$('#overlay').hidden;},
 open(section,title,body,actions,type=''){
  if(game?.running)game.setPaused(true);current=type;$('#overlay').dataset.menu=type;
  $('#overlay-eyebrow').textContent=section;$('#overlay-title').textContent=title;$('#overlay-body').innerHTML=body;
  const container=$('#overlay-actions');container.replaceChildren();for(const a of actions){const b=document.createElement('button');b.textContent=a.label;b.className=a.primary?'primary':'';b.disabled=!!a.disabled;b.onclick=a.action;container.append(b);}
  $('#overlay').hidden=false;requestAnimationFrame(()=>container.querySelector('button:not(:disabled)')?.focus({preventScroll:true}));
 },
 close(){if(current==='settings'){game.sound.setVolume(settings.volume);game.voice.setVolume();}if(returnMenu==='pause'&&current!=='pause'){returnMenu='';this.pause();returnMenu='';return;}if(current==='death'||current==='ending'){this.home();return;}$('#overlay').hidden=true;current='';returnMenu='';if(game?.running){this.showGame();game.setPaused(false);}},
 back(){game.sound.setVolume(settings.volume);game.voice.setVolume();if(returnMenu==='pause'){this.pause();returnMenu='';}else this.close();},
 updateContinue(){const save=game?.readSave();$('#continue-game').hidden=!save;$('#save-label').textContent=save?`Chapter ${CHAPTERS[save.chapter].number} · ${CHAPTERS[save.chapter].place.split(' / ')[0]}`:'';},
 showGame(){$('#title').hidden=true;$('#hud').hidden=false;$('#touch-controls').hidden=!matchMedia('(pointer: coarse)').matches;},
 home(){game.cinema.cancel();game.voice.stop();game.running=false;game.setPaused(true);$('#overlay').hidden=true;$('#hud').hidden=true;$('#touch-controls').hidden=true;$('#chapter-card').hidden=true;$('#title').hidden=false;$('#damage').style.opacity=0;current='';returnMenu='';this.updateContinue();},
 resumeStory(goal){this.showGame();game.setPaused(false);game.player.inv=Math.max(game.player.inv,2);game.radioUntil=0;$('#radio').style.opacity=0;
  if(goal){$('#chapter-card h2').textContent=goal;$('#chapter-card .eyebrow').textContent=`Chapter ${game.config.number}`;$('#chapter-card').hidden=false;this.cardUntil=game.time+4.5;}
 },
 updateStory(t){if(t>(this.cardUntil||0))$('#chapter-card').hidden=true;},
 intro(c){const id=['opening','descent','return'][game.chapter];game.cinema.play(id,()=>{game.seenScenes.add(id);game.allies.add(game.chapter);game.save();this.resumeStory(game.level.tasks[game.objectives]);game.radio(...game.level.cues[game.objectives],7);if(id==='opening')$('#chapter-card .eyebrow').textContent='Three days later · 3:04 AM';game.player.yaw=0;game.player.pitch=0;});},
 async load(n,run){
  if(game.loading)return;const c=CHAPTERS[n],screen=$('#loading-screen');screen.hidden=false;$('#loading-chapter').textContent='CHAPTER '+c.number;$('#loading-location').textContent=c.place.split(' / ')[0];$('#loading-hint').textContent=['Keep moving. Use cover when changing a magazine.','A voice can be borrowed. A name has to be remembered.','Their armor breaks during recovery. Make the opening count.'][n];
  const progress=p=>{$('#loading-fill').style.width=(p*100)+'%';$('#loading-track').setAttribute('aria-valuenow',Math.round(p*100));};progress(0);
  try{await game.prepareRun(n,run,progress);$('#overlay').hidden=true;}catch(error){console.error(error);this.open('Loading failed','The signal was lost.','<p>Refresh to download the remaining assets.</p>',[{label:'Retry',primary:true,action:()=>location.reload()}],'loading');}finally{screen.hidden=true;}
 },
 start(){returnMenu='';this.open('New game','Choose difficulty',`<div class="difficulty-list"><label><input type="radio" name="difficulty" value="story"><span>Story<small>A gentler fight. More room to explore.</small></span></label><label><input type="radio" name="difficulty" value="survivor" checked><span>Survivor<small>Stay alert. Make every round count.</small></span></label><label><input type="radio" name="difficulty" value="nightmare"><span>Nightmare<small>Relentless enemies. Little room for mistakes.</small></span></label></div><p class="muted">Your progress is saved in this browser. Includes AI-generated character voices.</p>`,[{label:'Start game',primary:true,action:async()=>{const d=$('input[name="difficulty"]:checked').value,b=$('#overlay-actions button');b.disabled=true;b.textContent='Loading…';game.sound.init();try{await this.load(0,()=>game.newGame(d));}catch(error){console.error(error);this.open('Loading failed','The school could not load.','<p>Refresh to download the remaining textures.</p>',[{label:'Retry',primary:true,action:()=>location.reload()}],'loading');}}},{label:'Back',action:()=>this.close()}],'start');},
 guide(){if(current==='pause')returnMenu='pause';this.open('Controls','Survive the night','<div class="control-grid">'+controls.map(([a,b])=>`<div><span>${a}</span><kbd>${b}</kbd></div>`).join('')+'</div><p class="muted">Find the shotgun in the survivors’ shelter and the carbine in the compass store. Press 1, 2 or 3, or use the wheel, to switch. Shotgun shells load one at a time; firing interrupts the reload. Headshots do double damage. Dodge outside attack warnings. Interrupt spitters with a headshot. Hit Birdy twice during a grounded charge tell. Shoot the speaking head of Jakob and Bobby, then lure them beneath the press during the chase. Let Chris hit a wall; steam and purge switches expose their bosses. The knife never runs out. Blue terminals save and heal.</p><p class="muted">If mouse capture is unavailable, hold right click and drag to look. On touch: left stick moves, right side looks.</p>',[{label:'Back',primary:true,action:()=>this.back()}],'guide');},
 settings(){if(current==='pause')returnMenu='pause';this.open('Options','Settings',`<div class="setting"><label for="sensitivity">Mouse sensitivity</label><input id="sensitivity" type="range" min=".3" max="2.5" step=".1" value="${settings.sensitivity}"></div><div class="setting"><label for="fov">Field of view</label><input id="fov" type="range" min="60" max="95" value="${settings.fov}"></div><div class="setting"><label for="volume">Master volume</label><input id="volume" type="range" min="0" max="1" step=".05" value="${settings.volume}"></div><div class="setting"><label for="dialogue-volume">Dialogue volume</label><input id="dialogue-volume" type="range" min="0" max="1" step=".05" value="${settings.dialogueVolume}"></div><div class="setting"><label for="quality">Graphics</label><select id="quality"><option value="high">High</option><option value="low">Performance</option></select></div><div class="setting"><label for="subtitles">Dialogue subtitles</label><input id="subtitles" type="checkbox" ${settings.subtitles?'checked':''}></div><div class="setting"><label for="motion">Reduce camera motion</label><input id="motion" type="checkbox" ${settings.motion?'checked':''}></div><p class="muted">Spoken dialogue plays throughout the story. Subtitles are optional. Cutscenes can be paused or skipped.</p>`,[{label:'Apply',primary:true,action:async()=>{const oldQuality=settings.quality,button=$('#overlay-actions button');game.applyingGraphics=true;for(const b of $('#overlay-actions').children)b.disabled=true;button.textContent='Applying…';settings.volume=Number($('#volume').value);settings.dialogueVolume=Number($('#dialogue-volume').value);settings.quality=$('#quality').value;settings.subtitles=$('#subtitles').checked;settings.motion=$('#motion').checked;settings.sensitivity=Number($('#sensitivity').value);settings.fov=Number($('#fov').value);game.sound.setVolume(settings.volume);game.voice.setVolume();try{await applyGraphics(game.world,settings.quality,game.running&&oldQuality!==settings.quality);}catch(error){game.applyingGraphics=false;settings.quality=oldQuality;$('#quality').value=oldQuality;for(const b of $('#overlay-actions').children)b.disabled=false;button.textContent='Apply';$('#overlay-body .muted').textContent='The graphics change could not finish. Your previous graphics setting has been restored.';return;}try{localStorage.setItem('resident-espey-settings',JSON.stringify(settings));}catch{}game.applyingGraphics=false;this.back();}},{label:'Back',action:()=>this.back()}],'settings');$('#quality').value=settings.quality;$('#volume').oninput=()=>{game.sound.setVolume(Number($('#volume').value));game.voice.setVolume(Number($('#volume').value),Number($('#dialogue-volume').value));};$('#dialogue-volume').oninput=()=>game.voice.setVolume(Number($('#volume').value),Number($('#dialogue-volume').value));},
 credits(){this.open('Resident Espey','Credits','<p>An original screen adaptation inspired by <em>The Chapa Trilogy II</em>: Ethan’s outbreak journal and the Backrooms stories.</p><p class="muted">Original game, characters, environments, sound design, and story adaptation. Character dialogue uses AI-generated voices, produced locally with Kokoro-82M and mastered for this game. Cinematic cover and surface textures generated for this game. Rendering: Three.js (MIT).</p><p class="muted">Survival-horror inspiration: Resident Evil. Independent project; not affiliated with Capcom.</p>',[{label:'Back',primary:true,action:()=>this.back()}],'credits');},
 pause(){returnMenu='pause';this.open(`Chapter ${game.config.number}`,'Paused',`<p class="pause-objective">${$('#objective').textContent}</p>`,[{label:'Resume',primary:true,action:()=>{returnMenu='';this.close();}},{label:'Controls',action:()=>this.guide()},{label:'Settings',action:()=>this.settings()},{label:'Fullscreen',action:async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{}this.close();}},{label:'Quit to title',action:()=>this.home()}],'pause');},
 page(n){const id=MEMORY_IDS[n];game.cinema.play(id,()=>{game.seenScenes.add(id);game.save();this.resumeStory(SCENES[id].goal);$('#chapter-card .eyebrow').textContent=id==='promise'?'The present · A choice remains':'Back to the present';});},
 journal(){returnMenu='';let body='<p class="muted">Memories '+game.pages.size+'/6 · Names kept '+game.allies.size+'/3</p><div class="memory-list">';for(let n=0;n<PAGES.length;n++){const seen=game.pages.has(n);body+=`<article><h3>${seen?SCENES[MEMORY_IDS[n]].label:'Undiscovered memory'}</h3>${seen?`<button data-replay="${n}">Replay scene</button><details><summary>Read notebook entry</summary><p>${PAGES[n].text}</p></details>`:'<p class="muted">Look for objects the school has left behind.</p>'}</article>`;}body+='</div>';this.open('Ethan’s notebook','Memories',body,[{label:'Return',primary:true,action:()=>this.close()}],'journal');document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>game.cinema.play(MEMORY_IDS[Number(b.dataset.replay)],()=>this.journal()));},
 map(){returnMenu='';this.open(game.config.place.split(' / ')[0],'Map','<div class="map-wrap"><canvas id="map-canvas" width="720" height="576" aria-label="Map showing Ethan, objectives, memories, checkpoints and exit"></canvas></div><div class="map-legend"><span><i></i>You</span><span><i class="gold"></i>Objective</span><span><i class="blue"></i>Save</span><span><i class="memory"></i>Memory</span><span><i class="red"></i>Exit</span></div>',[{label:'Return',primary:true,action:()=>this.close()}],'map');const c=$('#map-canvas'),ctx=c.getContext('2d'),s=24;
  ctx.fillStyle='#0d1718';ctx.fillRect(0,0,c.width,c.height);
  game.grid.forEach((row,z)=>row.forEach((v,x)=>{if(v)return;ctx.fillStyle='#34443f';ctx.fillRect(x*s,z*s,s,s);ctx.strokeStyle='#91a18f';ctx.lineWidth=1;
   for(const [dx,dz]of [[0,-1],[1,0],[0,1],[-1,0]])if(game.grid[z+dz]?.[x+dx]!==0){ctx.beginPath();if(dx){const edge=(x+(dx>0?1:0))*s;ctx.moveTo(edge,z*s);ctx.lineTo(edge,(z+1)*s);}else{const edge=(z+(dz>0?1:0))*s;ctx.moveTo(x*s,edge);ctx.lineTo((x+1)*s,edge);}ctx.stroke();}
  }));
  for(const r of game.level.rooms){const [a,b,c,d]=r.bounds;if(r.stage>game.objectives){ctx.fillStyle='#0d171890';ctx.fillRect(a*s,b*s,(c-a+1)*s,(d-b+1)*s);}ctx.fillStyle=r.stage<=game.objectives?'#c0ccba':'#657469';ctx.font='12px Arial';ctx.textAlign='center';ctx.fillText(r.name,(a+c+1)*s/2,(b+d+1)*s/2-16,(c-a+1)*s-14);}
  const dot=(x,z,color,r=5)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(x/TILE*s,z/TILE*s,r,0,Math.PI*2);ctx.fill();};
  game.items.forEach(i=>{if(i.used||Number.isInteger(i.stage)&&i.stage!==game.objectives)return;const r=game.level.rooms.find(r=>i.at[0]>=r.bounds[0]&&i.at[0]<=r.bounds[2]&&i.at[1]>=r.bounds[1]&&i.at[1]<=r.bounds[3]);if(r&&r.stage>game.objectives)return;dot(i.x,i.z,['fuse','seal','anchor'].includes(i.kind)?'#d6bf80':i.kind==='save'?'#76abc8':i.kind==='page'?'#d5d9c9':'#6b8b77',i.kind==='page'?5:4);});
  for(const g of game.world.gates){ctx.strokeStyle=g.obstacle.active?'#bd7258':'#8ca596';ctx.lineWidth=3;ctx.beginPath();const x=(g.at[0]+.5)*s,z=(g.at[1]+.5)*s;if(g.axis==='x'){ctx.moveTo(x,z-9);ctx.lineTo(x,z+9);}else{ctx.moveTo(x-9,z);ctx.lineTo(x+9,z);}ctx.stroke();}
  const ex=game.config.exit;dot((ex[0]+.5)*TILE,(ex[1]+.5)*TILE,'#bd6659',6);dot(game.player.x,game.player.z,'#e2edca',6);const p=game.player;ctx.strokeStyle='#e2edca';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(p.x/TILE*s,p.z/TILE*s);ctx.lineTo(p.x/TILE*s-Math.sin(p.yaw)*20,p.z/TILE*s-Math.cos(p.yaw)*20);ctx.stroke();},

 puzzle(){let seq=[];const names=['CURRENT','NORTH','HOME'];const render=(wrong=false)=>{this.open('The Geographer’s Seal','Align the memories',`<div class="seal-slots">${[0,1,2].map(i=>`<span>${seq[i]||'—'}</span>`).join('')}</div><p class="muted">${wrong?'The rings slip. Try again.':game.pages.has(3)?'Paul found the current. Johnson found north. The names lead home.':'Landon: “Current. North. Home. In that order.”'}</p>`,names.map(name=>({label:name,action:()=>{if(name===names[seq.length]){seq.push(name);game.sound.play('pickup');if(seq.length===3){game.puzzleSolved=true;$('#overlay').hidden=true;game.save();game.nextChapter();}else render();}else{seq=[];game.sound.play('empty');render(true);}}})).concat([{label:'Step back',action:()=>this.close()}]),'puzzle');};render();},
 finale(){game.cinema.play('choice',()=>{this.open('The last bell','Make your choice','<p>Behind you: the people the school has taken.<br>Before you: a door for one survivor.</p>',[{label:'Call everyone home',primary:true,action:()=>game.finish('remember')},{label:'Leave alone',action:()=>game.finish('seal')},{label:'Keep searching',action:()=>{this.close();this.showGame();}}],'finale');});},
 ending(type){game.cinema.play(type,()=>{const s=game.stats;this.open('Campaign complete',type==='home'?'You wrote us a way home.':type==='echoes'?'Some names are still missing.':'One survivor.',`<dl class="results"><div><dt>Time</dt><dd>${Math.floor(s.seconds/60)}:${String(Math.floor(s.seconds%60)).padStart(2,'0')}</dd></div><div><dt>Memories recovered</dt><dd>${game.pages.size} / 6</dd></div><div><dt>Accuracy</dt><dd>${s.shots?Math.round(s.hits/s.shots*100):0}%</dd></div></dl>${type!=='home'?'<p class="muted">Four memories and all three allies can bring everyone home.</p>':''}`,[{label:'Return to title',primary:true,action:()=>this.home()}],'ending');});},
 death(){this.open('','You died.','<p class="muted">Return to your latest checkpoint.</p>',[{label:'Retry',primary:true,action:()=>{$('#overlay').hidden=true;current='';this.load(game.checkpoint?.chapter??game.chapter,()=>game.retry());}},{label:'Quit to title',action:()=>this.home()}],'death');}
};
try{game=new Game(ui,settings);ui.updateContinue();window.ResidentEspey=Object.freeze({snapshot:()=>game.snapshot()});}catch(error){console.error('Unable to initialize Resident Espey:',error);$('#fatal').hidden=false;$('#title').hidden=true;}
$('#new-game').onclick=()=>ui.start();$('#continue-game').onclick=async()=>{game.sound.init();try{await ui.load(game.readSave()?.chapter??0,()=>{if(game.continueGame()&&!game.cinema.active)ui.showGame();});}catch(error){console.error(error);$('#fatal').hidden=false;}};
$('#how-to').onclick=()=>{returnMenu='';ui.guide();};$('#settings').onclick=()=>{returnMenu='';ui.settings();};$('#credits').onclick=()=>{returnMenu='';ui.credits();};$('#pause-button').onclick=()=>ui.pause();$('#map-button').onclick=()=>ui.map();$('#journal-button').onclick=()=>ui.journal();
document.addEventListener('keydown',e=>{if(e.code==='Tab'&&(ui.isOpen()||game?.cinema.active)){const host=game.cinema.active?$('#cinematic'):$('#overlay'),nodes=[...host.querySelectorAll('button:not(:disabled),select,input,summary')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});

requestAnimationFrame(()=>($('#continue-game').hidden?$('#new-game'):$('#continue-game')).focus({preventScroll:true}));
document.addEventListener('keydown',e=>{if(!$('#title').hidden&&!ui.isOpen()&&['ArrowUp','ArrowDown'].includes(e.code)){e.preventDefault();const buttons=[...document.querySelectorAll('.menu button')].filter(b=>!b.hidden),n=buttons.indexOf(document.activeElement);buttons[(n+(e.code==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus({preventScroll:true});}});
